package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamModern43GroupBank4 {
    private const val T = "නූතන බටහිර කලාව හා ශ්‍රී ලංකාවේ '43 කණ්ඩායම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("1943 දී '43 කණ්ඩායම පිහිටුවීමට පෙර යටත් විජිත ලංකාවේ පැවති 'ලංකා කලා සංගමය' (Ceylon Society of Arts) අනුගමනය කළ ශෛලිය කුමක්ද?", "බ්‍රිතාන්‍ය ඇකඩමික් යථාර්ථවාදය", "නූතන වියුක්ත ප්‍රකාශනවාදය", "කියුබිසම් හා ෆියුචරිසම්", "පොප් ආර්ට් හා ඩිජිටල් කලාව", "සම්ප්‍රදායික බ්‍රිතාන්‍ය වික්ටෝරියානු ඇකඩමික් සිතුවම් ආරට එරෙහිව නිදහස් කලා ප්‍රකාශනයක් සඳහා '43 කණ්ඩායම බිහි විය."),
        q("20 වන සියවස මුල ශ්‍රී ලංකාවේ 'මුදලියර් ඒ.සී.ජී.එස්. අමරසේකර' ප්‍රකට වූයේ කුමන සිතුවම් මාධ්‍යය හා ශෛලිය සඳහාද?", "යථාර්ථවාදී ජල සායම් හා තෙල් සායම් ආලේඛ්‍ය", "මහනුවර යුගයේ තෙත් බදාම බිතුසිතුවම්", "වියුක්ත කළු සුදු කොලාජ් නිර්මාණ", "ලෝහ වාත්තු භූමි මූර්ති", "ගැමි ජීවිතය, භූ දර්ශන හා ප්‍රභූ ආලේඛ්‍ය චිත්‍ර ඇකඩමික් යථාර්ථවාදීව ඇඳීමට අමරසේකර මහතා ප්‍රසිද්ධ විය."),
        q("ශ්‍රී ලංකාවේ පළමු රජයේ කලා විද්‍යාලයේ (හේවුඩ් ආයතනය) ප්‍රථම ශ්‍රී ලාංකික විදුහල්පතිවරයා වූ ප්‍රකට ආලේඛ්‍ය චිත්‍ර ශිල්පියා කවුද?", "ජේ.ඩී.ඒ. පෙරේරා (J.D.A. Perera)", "ජෝර්ජ් කීට් (George Keyt)", "අයිවන් පීරිස් (Ivan Peries)", "චන්ද්‍රගුප්ත තේනුවර", "1952 දී රජයේ ලලිත කලායතනය ආරම්භ කරමින් ජේ.ඩී.ඒ. පෙරේරා මහතා දේශීය කලා අධ්‍යාපනයට පදනම දැමීය."),
        q("ශ්‍රී ලංකාවේ 'ඩේවිඩ් පේන්ටර්' (David Paynter) කලාකරුවා නිමැවූ සුප්‍රකට දේවස්ථාන බිතුසිතුවම් මාලාව පිහිටා ඇත්තේ කොහේද?", "මහනුවර ත්‍රිත්ව විද්‍යාලීය දෙව්මැදුරේ", "බොරැල්ල ගෝතමී විහාරයේ", "කැලණිය රජමහා විහාරයේ", "තොටගමුව විජයබා පිරිවෙනේ", "බයිබල් කතා ශ්‍රී ලාංකික පරිසරයට හා ලාංකේය මුහුණුවරට අනුව ඔහු ත්‍රිත්ව විද්‍යාල දෙව්මැදුරේ සිතුවම් කළේය."),
        q("ශ්‍රී ලංකාවේ බෞද්ධ පුනර්ජීවන යුගයේදී විහාරස්ථානවල බිතුසිතුවම් හා දේව රූප මුද්‍රිත ලිතොග්‍රැෆ් පෝස්ටර් ලෙස නිවෙස්වලට ගෙන ආ ශිල්පියා කවුද?", "එම්. සාලිස් (M. Sarlis)", "ලයනල් වෙන්ඩ්ට් (Lionel Wendt)", "හැරී පීරිස් (Harry Pieris)", "ජස්ටින් දැරණියගල (Daraniyagala)", "මාලිගාවත්තේ සාලිස් මහතා කොළඹ මාලිගාකන්ද ආශ්‍රිතව බටහිර ත්‍රිමාණ ඡායා ක්‍රමය විහාර චිත්‍රයට එක් කළේය."),
        q("කැලණිය රජමහා විහාරයේ නව බිතුසිතුවම් නිර්මාණය කළ 'සොලියස් මෙන්ඩිස්' ශිල්පියා තම චිත්‍ර ශෛලිය ගොඩනගා ගැනීමට අධ්‍යයනය කළේ මොනවාද?", "අජන්තා, සීගිරි හා පොළොන්නරු සම්භාව්‍ය සිතුවම්", "යුරෝපීය පොප් ආර්ට් හා ග්‍රැෆිටි", "මිසර හයිරෝග්ලිෆික් ගල් කැටයම්", "ඇමරිකානු වියුක්ත තීන්ත ඉසීම්", "පැරණි ලාංකේය හා ඉන්දියානු සම්භාව්‍ය බිතුසිතුවම් ආභාසයෙන් සොලියස් මෙන්ඩිස් දේශීය බෞද්ධ සිතුවම් නවීකරණය කළේය."),
        q("1943 නොවැම්බර් මාසයේදී '43 කණ්ඩායමේ පළමු ප්‍රදර්ශනය පැවැත්වූ කොළඹ ගොඩනැගිල්ල කුමක්ද?", "ඩාර්ලි පාරේ හේවුඩ් මන්දිරයේ උඩුමහලේ", "නෙළුම් පොකුණ රඟහලේ", "ලයනල් වෙන්ඩ්ට් කලාගාරයේ", "කොළඹ ජාතික කෞතුකාගාරයේ", "පසුව කලායතනය පිහිටි ඩාර්ලි පාරේ අංක 75 (හේවුඩ්) හිදී '43 කණ්ඩායමේ පළමු ප්‍රදර්ශනය පැවැත්විණි."),
        q("1943 කණ්ඩායමේ සාමාජිකයන් අතරින් කවියෙකු හා චිත්‍ර ශිල්පියෙකු ලෙස මෙන්ම පළමු සම්පූර්ණ විලාසිතාවට හිමිකම් කී කලාකරුවා කවුද?", "ජෝර්ජ් කීට් (George Keyt)", "සොලියස් මෙන්ඩිස්", "ඒ.සී.ජී.එස්. අමරසේකර", "බෙලින්ග් (W.J.G. Beling)", "ජෝර්ජ් කීට් කවි පොත් රචනා කරමින් ඉන්දියානු සංස්කෘතිය හා නූතන කියුබිසම් කලාව එක් කළේය."),
        q("ජෝර්ජ් කීට් විසින් 'ගෝතමී විහාරයේ' බිතුසිතුවම් නිර්මාණය කිරීමේදී ඒ සඳහා ආරාධනා කළ හා අනුග්‍රහය දැක්වූ දායක පවුල කුමක්ද?", "හැරල්ඩ් පීරිස් මහතා හා ඔහුගේ පවුල", "ඩොන් ස්ටීවන් සේනානායක මහතා", "මුදලියර් අමරසේකර පවුල", "මේජර් හේවුඩ් මහතා", "හැරල්ඩ් පීරිස්ගේ ආරාධනයෙන් 1939–1940 කාලයේ බොරැල්ල ගෝතමී විහාරයේ සුප්‍රකට බුද්ධ චරිත සිතුවම් ඇඳුණි."),
        q("ජෝර්ජ් කීට්ගේ 'නායිකා' හෝ කාන්තා රූප සිතුවම්වල මුහුණු එකවර පැතිකඩෙන් හා ඉදිරියෙන් පෙනෙන ලෙස ඇඳීමට බලපෑ බටහිර ශෛලිය කුමක්ද?", "පැබ්ලෝ පිකාසෝගේ කියුබිසම් (Cubism)", "පෝල් සිග්නැක්ගේ පොයින්ටිලිසම්", "ජැක්සන් පොලොක්ගේ ඇක්ෂන් පේන්ටින්", "ඇන්ඩි වෝහෝල්ගේ පොප් ආර්ට්", "කීට් පිකාසෝගේ බහු-කෝණික කියුබිසම් රේඛාව ලාංකේය හා ඉන්දියානු ගැමි රිද්මය සමඟ මුසු කළේය."),
        q("'43 කණ්ඩායමේ ආරම්භක ලේකම්වරයා ලෙස කටයුතු කළ, පැරීසියේදී පුහුණු වූ කීර්තිමත් ආලේඛ්‍ය චිත්‍ර ශිල්පියා කවුද?", "හැරී පීරිස් (Harry Pieris)", "ජස්ටින් දැරණියගල", "මංජු ශ්‍රී (L.T.P. Manjusri)", "ඕබ්‍රි කොලට් (Aubrey Collette)", "කොළඹ බාන්ස් පෙදෙසේ පිහිටි ඔහුගේ නිවස වත්මන් 'සපුමල් පදනම' කලාගාරය ලෙස සුරැකිව පවතී."),
        q("'43 කණ්ඩායමේ ආරම්භක සාමාජික 'අයිවන් පීරිස්' (Ivan Peries) ප්‍රධාන වශයෙන් සිතුවම් කළ සුප්‍රකට තේමාව කුමක්ද?", "මුහුදු වෙරළ, රළ, බෝට්ටු හා නිහඬ පවුල් ජීවිතය", "රජ මාලිගාවල යුද සටන් පෙළ", "කර්මාන්තශාලා යන්ත්‍ර හා දුම්රිය", "වියුක්ත කළු සුදු ජ්‍යාමිතික රටා", "ඔහුගේ 'ද රිටර්න්' (The Return) හා 'ද වේව්' වැනි සිතුවම් ගැඹුරු ශෝකී නිහඬ බවක් හා සරල පැතලි වර්ණ පෙන්වයි."),
        q("1956 බ්‍රසීලයේ 'සාවෝ පෝලෝ' හා 'වෙනීසියානු බියෙනාලේ' ජාත්‍යන්තර ප්‍රදර්ශනවල ශ්‍රී ලංකාව නියෝජනය කර ඇගයුම් ලැබූ '43 කණ්ඩායමේ ශිල්පියා කවුද?", "ජස්ටින් දැරණියගල (Justin Daraniyagala)", "ඩේවිඩ් පේන්ටර් (David Paynter)", "එම්. සාලිස් (M. Sarlis)", "සොලියස් මෙන්ඩිස් (Soliyas Mendis)", "ප්‍රබල ප්‍රකාශනවාදී මානව හැඟීම් හා තද තෙල් සායම් ස්තර දැරණියගලගේ ජාත්‍යන්තර කෘතිවල ලක්ෂණයකි."),
        q("රේඛා චිත්‍ර, ලී කැටයම් මෙන්ම 'කුකුළු පොර' හා 'අම්මා සහ දරුවා' වැනි ගැමි තේමා සිතුවම් කළ '43 කණ්ඩායමේ ශිල්පියා කවුද?", "රිචඩ් ගේබ්‍රියල් (Richard Gabriel)", "ලයනල් වෙන්ඩ්ට් (Lionel Wendt)", "ජෝර්ජ් ක්ලාසන් (George Claessen)", "ඩබ්ලිව්.ජේ.ජී. බෙලින්ග් (Beling)", "රෝමානු කතෝලික පසුබිම හා ශ්‍රී ලාංකික ගැමි සතුන්, කුරුල්ලන් ගේබ්‍රියල් සිය සිතුවම්වල සංවේදීව ඇන්දේය."),
        q("ශ්‍රී ලංකාවේ චිත්‍ර කලා ඉතිහාසයේ ප්‍රකට පුවත්පත් දේශපාලන කාටූන් ශිල්පියෙකු වූ '43 කණ්ඩායමේ සාමාජිකයා කවුද?", "ඕබ්‍රි කොලට් (Aubrey Collette)", "ජෝර්ජ් කීට් (George Keyt)", "හැරී පීරිස් (Harry Pieris)", "ජෝර්ජ් ක්ලාසන් (Claessen)", "දැඩි විවේචනාත්මක හා හාස්‍යජනක රේඛා කාටූන් සඳහා ඕබ්‍රි කොලට් 1940–50 දශකවල ඉමහත් ජනප්‍රිය විය."),
        q("ලංකාවේ කැලෑබද පැරණි විහාරස්ථාන රැසක මහනුවර යුගයේ බිතුසිතුවම් විනාශ වීමට පෙර ඒවා පිටපත් කර රැකගත් ශිල්පියා කවුද?", "එල්.ටී.පී. මංජු ශ්‍රී (L.T.P. Manjusri)", "තිස්ස රණසිංහ (Tissa Ranasinghe)", "එච්.ඒ. කරුණාරත්න (H.A. Karunaratne)", "සේනක සේනානායක (Senaka Senanayake)", "විහාර බිතුසිතුවම් සිය ගණනක් පරිමාණානුකූලව පිටපත් කිරීම වෙනුවෙන් මංජු ශ්‍රී මහතා රැමෝන් මැග්සේසේ සම්මානය දිනීය."),
        q("1943 කණ්ඩායමේ ආරම්භකයන් අතර සිටි, ඕස්ට්‍රේලියාවට ගොස් වියුක්ත සිතුවම් කළ හා චිත්‍ර පාසල් පරීක්ෂකවරයෙකු වූ ශිල්පියා කවුද?", "ඩබ්ලිව්.ජේ.ජී. බෙලින්ග්", "සරත් චන්ද්‍රජීව", "ස්ටැන්ලි කිරින්දේ", "ජගත් වීරසිංහ", "ලංකාවේ පාසල් චිත්‍ර කලා විෂය නිර්දේශය නිදහස් ළමා ප්‍රකාශනයක් බවට පත් කිරීමට බෙලින්ග් මූලික විය."),
        q("'43 කණ්ඩායමේ ආරම්භක සාමාජික 'ජෝර්ජ් ක්ලාසන්' (George Claessen) ජීවත්ව සිටියදී වඩාත් ප්‍රසිද්ධ වූයේ කුමන ශෛලියකටද?", "පිරිසිදු වියුක්ත රේඛා හා ජ්‍යාමිතික හැඩතල", "සාම්ප්‍රදායික කැන්ඩියන් ලියවැල් ඇඳීම", "වෙස්මුහුණු හා කෝලම් රූකඩ කැපීම", "මිසර රජ ප්‍රතිමා පිටපත් කිරීම", "ශ්‍රී ලංකාවෙන් ලන්ඩනයට ගිය ක්ලාසන් සම්පූර්ණ වියුක්ත කලාව (Pure Abstraction) වර්ධනය කළ පුරෝගාමියෙකි."),
        q("ලාංකේය මධ්‍යකාලීන කලා ශිල්ප ලොවට හඳුන්වා දුන් 'මධ්‍යකාලීන සිංහල කලා' (Mediaeval Sinhalese Art) ග්‍රන්ථයේ කර්තෘ කවුද?", "ආනන්ද කුමාරස්වාමි", "ලයනල් වෙන්ඩ්ට්", "හැරී පීරිස්", "ජෝර්ජ් කීට්", "1908 දී ප්‍රකාශිත මෙම ග්‍රන්ථය ශ්‍රී ලංකාවේ සාම්ප්‍රදායික කලා සම්ප්‍රදාය පිළිබඳ විශිෂ්ට මූලාශ්‍රයකි."),
        q("ලයනල් වෙන්ඩ්ට් (Lionel Wendt) විසින් ශ්‍රී ලංකාවේ ඡායාරූප කලාවට හඳුන්වා දුන් සුවිශේෂී අඳුරු කාමර (Darkroom) තාක්ෂණය කුමක්ද?", "සෝලරයිසේෂන් හා ඡායාරූප මොන්ටාජ්", "ඩිජිටල් ත්‍රිමාණ මුද්‍රණය", "රන් තහඩු මත ඇඹරීම", "තෙල් සායම් අතින් ආලේප කිරීම", "සරියලිසම් හා නූතනවාදී ආභාසය ලත් වෙන්ඩ්ට් ශ්‍රී ලාංකේය රූප හා පරිසරය කලාත්මකව ඡායාරූපගත කළේය."),
        q("කොළඹ 7 ගිල්ෆර්ඩ් ක්‍රෙසන්ට්හි පිහිටි සුප්‍රකට 'ලයනල් වෙන්ඩ්ට් කලා මධ්‍යස්ථානය' විවෘත කරන ලද්දේ කවරෙකු සිහිපත් කිරීමටද?", "ලයනල් වෙන්ඩ්ට් ශූරීන්", "සොලියස් මෙන්ඩිස් ශූරීන්", "හෙන්රි ධර්මසේන ශූරීන්", "ආනන්ද කුමාරස්වාමි ශූරීන්", "1953 දී විවෘත කෙරුණු මෙම මධ්‍යස්ථානය දශක ගණනාවක් පුරා ශ්‍රී ලංකාවේ නූතන චිත්‍ර හා නාට්‍ය කලාවේ කේන්ද්‍රස්ථානය විය."),
        q("1960–70 දශකවල ශ්‍රී ලංකාවේ සම්පූර්ණ වියුක්ත කලාව හා 'ඇසෙම්බ්ලේජ්' (Assemblage) කෘති නිර්මාණය කළ ප්‍රමුඛ කලාකරුවා කවුද?", "එච්.ඒ. කරුණාරත්න (H.A. Karunaratne)", "මුදලියර් අමරසේකර", "ඩේවිඩ් පේන්ටර්", "ජේ.ඩී.ඒ. පෙරේරා", "ජපානයේ හා ඇමරිකාවේ පුහුණුව ලද එච්.ඒ. කරුණාරත්න ඉවතලන ද්‍රව්‍ය හා වියුක්ත රේඛා කලාවට ගෙන ආවේය."),
        q("ශ්‍රී ලංකාවේ නූතන ලෝකඩ මූර්ති කලාවේ පුරෝගාමියෙකු වූ 'තිස්ස රණසිංහ' නිමැවූ ලෝක ප්‍රකට මූර්ති මාධ්‍යය කුමක්ද?", "ටෙරාකොටා හා ලෝකඩ වාත්තු (Bronze casting)", "ප්ලාස්ටික් ත්‍රිමාණ මුද්‍රණය", "රෙදි හා බතික් මූර්ති", "අයිස් හා ඉටි කැටයම්", "මිනිස් ශරීරයේ අධ්‍යාත්මික බව ප්‍රකට කරන 'පැවිදි රූප' හා ප්‍රසිද්ධ චරිත මූර්ති ඔහු ලෝකඩින් නිමැවීය."),
        q("ශ්‍රී ලංකාවේ සාම්ප්‍රදායික ගැමි ජීවිතය, වැව් බැඳි රාජ්‍යය හා පෞරාණික සිද්ධි ගැඹුරු රේඛා හා පැතලි වර්ණවලින් ඇඳි ශිල්පියා කවුද?", "ස්ටැන්ලි කිරින්දේ (Stanley Kirinde)", "විලෙම් ද කූනිං", "ඇන්ඩි වෝහෝල්", "කසිමීර් මැලෙවිච්", "පුරාවිද්‍යාත්මක හා ඓතිහාසික දැනුම භාවිත කරමින් කිරින්දේ මහතා අනුරාධපුර හා ගැමි පරිසරය සිතුවමට නැඟීය."),
        q("වර්ණවත් ශ්‍රී ලාංකික වනාන්තර, සතුන් හා මල් ලෝක පූජිත ලෙස සිතුවම් කරන ළමා වියේ සිට ප්‍රකට වූ ශිල්පියා කවුද?", "සේනක සේනානායක (Senaka Senanayake)", "ඔගස්ට් රොඩින්", "හෙන්රි මැටිස්", "පීට් මොන්ඩ්‍රියන්", "පරිසර සංරක්ෂණය තේමා කරගත් ඔහුගේ දීප්තිමත් වැසි වනාන්තර සිතුවම් ලොව පුරා ප්‍රකටය."),
        q("ශ්‍රී ලංකාවේ පුවත්පත් චිත්‍ර කතා (Comic art) හා ළමා පොත් සිතුවම් කලාව නගා සිටුවීමේ පුරෝගාමියා ලෙස සැලකෙන්නේ කවුද?", "ජී.එස්. ප්‍රනාන්දු හා සුසිල් ප්‍රේමරත්න", "ජැක්සන් පොලොක් හා රොත්කෝ", "සැල්වදෝර් ඩාලි හා මිරෝ", "ගුස්ටාව් ක්ලිම්ට් හා මන්ච්", "පත්තර හා ළමා කතා පොත් සඳහා දේශීය අනන්‍යතාවකින් යුත් රේඛා සිතුවම් මොවුන් හඳුන්වා දුන්හ."),
        q("සිංහල ළමා පොත් සිතුවම් කලාවේ 'කුඩ හොරා' වැනි අමරණීය චරිත නිර්මාණය කළ ජාත්‍යන්තර සම්මානලාභී කලාකාරිනිය කවුද?", "සයිබිල් වෙත්තසිංහ (Sybil Wettasinghe)", "ෆ්‍රීඩා කාලෝ (Frida Kahlo)", "බ්‍රිජට් රයිලි (Bridget Riley)", "ජෝර්ජියා ඕ'කීෆ් (O'Keeffe)", "සරල ජන සම්ප්‍රදායික රේඛා හා ගැමි හාස්‍යය ඇසුරෙන් සයිබිල් වෙත්තසිංහ මහත්මිය ලාංකේය ළමා චිත්‍ර හැඩගැස්වූවාය."),
        q("ශ්‍රී ලංකාවේ පොදු අවකාශ හා උසස් ආලේඛ්‍ය මූර්ති නිර්මාණයේ නිරත ප්‍රකට සමකාලීන මූර්ති ශිල්පියෙකු හා මහාචාර්යවරයෙකු කවුද?", "සරත් චන්ද්‍රජීව", "පෝල් සෙසෑන්", "ජෝර්ජස් සූරා", "ක්ලෝඩ් මොනේ", "ටෙරාකොටා හා ලෝකඩ මූර්ති මෙන්ම පාර්ලිමේන්තු හා පොදු ස්ථාන සඳහා කළ නිර්මාණවලින් ඔහු ප්‍රකටය."),
        q("ජෙෆ්රි බාවාගේ ගෘහ නිර්මාණ සඳහා ඉහළ සිවිලිම් සරසන විශාල 'බතික් බැනර්' හා 'ඩුම්බර' මෝස්තර නවීකරණය කළ ශිල්පිනිය කවුද?", "ඊනා ද සිල්වා (Ena de Silva)", "රෝසා බොන්හර්", "හැනා හොච්", "බාබරා හෙප්වර්ත්", "දේශීය හස්ත කර්මාන්ත හා බතික් කලාව නූතන ගෘහ නිර්මාණ අලංකරණය සමඟ ඊනා ද සිල්වා සම්බන්ධ කළාය."),
        q("දේශීය අත්යන්ත්‍ර රෙදි විවීමේ (Handloom) කලාව වර්ණ හා වයනයෙන් නවීකරණය කර 'බෙයාෆුට්' (Barefoot) ආයතනය බිහි කළ ශිල්පිනිය කවුද?", "බාබරා සැන්සෝනි (Barbara Sansoni)", "මේරි කැසැට්", "යයෝයි කුසාමා", "තමාරා ඩි ලෙම්පිකා", "ලාංකේය ස්වභාවික පරිසරයේ වර්ණ අත්යන්ත්‍ර රෙදිපිළිවලට ගෙන ඒමට බාබරා සැන්සෝනි මහත්මිය පුරෝගාමී විය."),
        q("ශ්‍රී ලංකාවේ ගඩොල්, දැව හා පරිසරයට ගැළපෙන වාතාශ්‍රය යොදා 'නිවර්තන නූතනවාදී' (Tropical Modernism) වාස්තු කලාව බිහි කළේ කවුද?", "ජෙෆ්රි බාවා (Geoffrey Bawa)", "ලේ කොර්බුසියේ (Le Corbusier)", "වෝල්ටර් ග්‍රෝපියස් (Gropius)", "මයිකල් ආන්ජලෝ (Michelangelo)", "ලුණුගඟ, කණ්ඩලම හෝටලය හා ශ්‍රී ජයවර්ධනපුර පාර්ලිමේන්තුව බාවාගේ විශිෂ්ට වාස්තු නිර්මාණ වේ."),
        q("ජෙෆ්රි බාවාගේ කණ්ඩලම හා බෙන්තොට හෝටල් වැනි ස්ථානවල පිත්තල, යකඩ හා තඹ මූර්ති නිර්මාණය කළ සහෝදර කලාකරුවා කවුද?", "ලකී සේනානායක (Laki Senanayake)", "මයිරන් (Myron)", "ෆීඩියාස් (Phidias)", "දොනතෙල්ලෝ (Donatello)", "පක්ෂීන්, බකමූණන් හා ගස්වැල් ආකාරයේ ලෝහ මූර්ති හා සිතුවම් නිර්මාණයට ලකී සේනානායක ඉමහත් ප්‍රසිද්ධය."),
        q("ශ්‍රී ලංකාවේ '90 දශකයේ කලා ප්‍රවණතාව' (90s Trend) නව්‍ය මාවතකට ගෙන ඒමට මූලික වූ 'විභවි ලලිත කලා ඇකඩමිය' පිහිටුවූ කලාකරුවා කවුද?", "චන්ද්‍රගුප්ත තේනුවර", "මුදලියර් අමරසේකර", "සොලියස් මෙන්ඩිස්", "හැරී පීරිස්", "1993 දී ආරම්භ කළ විභවි ඇකඩමිය හරහා සමකාලීන සමාජ-දේශපාලනික කලා ප්‍රකාශනය ශ්‍රී ලංකාවේ ව්‍යාප්ත විය."),
        q("ශ්‍රී ලංකාවේ '90 දශකයේ ප්‍රවණතාව' (90s Trend) යන යෙදුම හඳුන්වා දුන් 'මුළු ඇඟ පුරා දේශපාලනික හා නාගරික අත්දැකීම්' සිතුවම් කළ ශිල්පියා කවුද?", "ජගත් වීරසිංහ (Jagath Weerasinghe)", "අයිවන් පීරිස් (Ivan Peries)", "එල්.ටී.පී. මංජු ශ්‍රී (Manjusri)", "ජී.එස්. ප්‍රනාන්දු (G.S. Fernando)", "ඔහුගේ 'කාංසාව' (Anxiety) වැනි සිතුවම් ප්‍රදර්ශන සමකාලීන ලාංකේය කලාවේ නව හැරවුමක් සනිටුහන් කළේය."),
        q("චන්ද්‍රගුප්ත තේනුවරගේ 'බැරලිසම්' (Barrelism) සංකල්පයේදී යුද බැරල් හා හමුදා සංකේත යොදා ඔහු ප්‍රකාශ කළේ කුමක්ද?", "යුද්ධය හා නාගරික ආරක්ෂක බාධක ජීවිතයට කළ බලපෑම", "පැරණි කෘෂිකාර්මික වාරි කර්මාන්තයේ දියුණුව", "පුරාණ ග්‍රීක මැටි බඳුන් කලාවේ ඉතිහාසය", "විවිධ රසායනික තීන්ත මිශ්‍ර කිරීමේ ක්‍රම", "එදිනෙදා කොළඹ මාර්ගවල තැබූ තාර බැරල් කැමෆ්ලාජ් රටාවෙන් සිතුවම් හා ස්ථාපන කලාවට ඔහු ගෙන ආවේය."),
        q("කැඩුණු පොත්පත්, පත්තර හා ලී කැබලි යොදා යුද්ධයෙන් හා ප්‍රචණ්ඩත්වයෙන් තොර සාමය ගැන ස්ථාපන කෘති නිමවන සමකාලීන ලාංකේය ශිල්පියා කවුද?", "කිංස්ලි ගුණතිලක (Kingsley Gunatillake)", "ජෝර්ජ් කීට් (George Keyt)", "ඩේවිඩ් පේන්ටර් (David Paynter)", "මුදලියර් අමරසේකර", "වෙඩි තැබූ පොත් හා පිළිස්සුණු පිටු ඇසුරින් කිංස්ලි ගුණතිලක සමකාලීන ස්ථාපන කලා කෘති නිමවා ඇත."),
        q("ශ්‍රී ලංකාවේ නූතන චිත්‍ර කලාව හා නාට්‍ය වේදිකා පසුතල නිර්මාණය සමඟ එක් වූ මහචාර්ය සරත්චන්ද්‍රගේ 'මනමේ' වේදිකා හා වෙස්මුහුණු සැලසුම් කළේ කවුද?", "සෝමබන්දු විද්‍යාපති", "මයිකල් ආන්ජලෝ", "ලියනාඩෝ ඩා වින්චි", "පැබ්ලෝ පිකාසෝ", "වේදිකා පසුතල, වර්ණ ආලෝකකරණය හා චිත්‍ර නිර්මාණයෙන් සෝමබන්දු විද්‍යාපති මහතා ලාංකේය කලාව පෝෂණය කළේය."),
        q("කැන්වස් මත විශාල පාපිසි, වෙළෙඳ බැනර් හා ශ්‍රී ලාංකික ජනප්‍රිය සංස්කෘතික රූප එක්කරන සමකාලීන කලා ව්‍යාපාරය කුමක්ද?", "සමකාලීන මිශ්‍ර මාධ්‍ය හා නව-පොප් කලාව", "ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර කලාව", "මහනුවර පෙතිකඩ සිතුවම් කලාව", "රෝම ආරුක්කු ඉදිකිරීම් කලාව", "තීර්ථ ජාත්‍යන්තර කලා සාමූහිකය වැනි කණ්ඩායම් හරහා සමකාලීන ලාංකේය ශිල්පීන් ජන සංස්කෘතිය කලාවට ගෙන ආහ."),
        q("ශ්‍රී ලංකාවේ 'තීර්ථ ජාත්‍යන්තර කලාකරුවන්ගේ සාමූහිකය' (Theertha) පිහිටුවීමේ ප්‍රධාන අරමුණ කුමක් වීද?", "විවිධ පළාත්වල සමකාලීන ශිල්පීන්ට සහය හා ප්‍රදර්ශන අවස්ථා දීම", "පුරාණ ශිලා ලිපි පිටපත් කර විකිණීම", "බටහිර සම්භාව්‍ය පිළිම පමණක් ගෙන්වීම", "පාසල් පෙළපොත් මුද්‍රණය පමණක් කිරීම", "සමකාලීන ස්ථාපන කලාව, කාර්ය සාධන කලාව (Performance) හා සාමූහික වැඩමුළු තීර්ථ හරහා ප්‍රවර්ධනය විය."),
        q("කවියෙකු හා ගීත රචකයෙකු මෙන්ම රජයේ කලායතනයේ පුහුණුව ලබා නූතන වියුක්ත සිතුවම් ඇඳි ලාංකේය ශිල්පියා කවුද?", "මහගම සේකර", "ක්ලෝඩ් මොනේ", "සැල්වදෝර් ඩාලි", "පීට් මොන්ඩ්‍රියන්", "සාම්ප්‍රදායික ලාංකේය හැඩතල නූතන රේඛා හා වර්ණවලින් ඉදිරිපත් කිරීමට මහගම සේකර සමත් විය."),
        q("'43 කණ්ඩායමේ ආරම්භක ශිල්පීන් අතරින් බෞද්ධ සංස්කෘතික කතා වෙනුවට ක්‍රිස්තියානි හා ගැමි මානුෂීය සම්බන්ධතා බහුලව ඇන්දේ කවුද?", "රිචඩ් ගේබ්‍රියල්", "සොලියස් මෙන්ඩිස්", "මංජු ශ්‍රී", "ජෝර්ජ් කීට්", "ගේබ්‍රියල්ගේ 'සර්පයන් නැටවීම' හා 'ගැලවුම්කරු' වැනි සිතුවම් දේශීය හා කිතුනු සංස්කෘතික සංකලනයක් පෙන්වයි."),
        q("ශ්‍රී ලංකාවේ බෞද්ධ විහාර චිත්‍ර කලාවට බටහිර ඡායාරූපමය ආලෝක-අඳුරු බව ගෙන ආ 'නව බෞද්ධ චිත්‍ර' රීතිය හැඳින්වෙන්නේ කෙසේද?", "බටහිරකරණය වූ පහතරට සංක්‍රාන්ති රීතිය", "ප්‍රාග් ඓතිහාසික ගල් ලෙන් රීතිය", "ශුද්ධ කියුබිසම් ජ්‍යාමිතික රීතිය", "ඇමරිකානු පොප් ආර්ට් රීතිය", "19 වන සියවස අග හා 20 මුලදී බටහිර ආභාසය සමඟ මිශ්‍ර වූ මෙම ශෛලිය ඊට පසු '43 කණ්ඩායම බිහිවීමට පසුබිම විය."),
        q("ශ්‍රී ලංකාවේ සෞන්දර්ය කලා විශ්වවිද්‍යාලය (UVPA) මුලින්ම ආරම්භ වූ විට ප්‍රකටව හැඳින්වූ නාමය කුමක්ද?", "රජයේ ලලිත කලායතනය (හේවුඩ් / Heywood)", "කොළඹ රාජකීය විද්‍යාලය", "පේරාදෙණිය ගෘහ නිර්මාණ පාසල", "මහනුවර තාක්ෂණික විද්‍යාලය", "හෝර්ටන් පෙදෙසේ හේවුඩ් මන්දිරයේ සිට වර්තමාන විශ්වවිද්‍යාලය දක්වා මෙම ආයතනය වර්ධනය විය."),
        q("1943 කණ්ඩායමට බලපෑ ඉන්දියානු පුනර්ජීවන කලා ව්‍යාපාරය (Bengal School) හා ශාන්තිනිකේතනය මෙහෙයවූයේ කවුද?", "රවීන්ද්‍රනාත් තාගෝර් හා නන්දලාල් බෝස්", "පැබ්ලෝ පිකාසෝ හා මැටිස්", "ඇන්ඩි වෝහෝල් හා පොලොක්", "රෙම්බ්‍රාන්ඩ් හා වර්මියර්", "ශ්‍රී ලාංකේය කලාකරුවන් කිහිප දෙනෙකුම ශාන්තිනිකේතනයේ අධ්‍යාපනය ලබා පෙරදිග රේඛා කලාව ඉගෙන ගත්හ."),
        q("ශාන්තිනිකේතනයේ අධ්‍යාපනය ලබා පැමිණි, සිංහල ජන කතා හා ගැමි රිද්මය මෘදු ජල සායම් සිතුවමට නැඟූ ලාංකේය ශිල්පියා කවුද?", "සෝමබන්දු විද්‍යාපති හා මංජු ශ්‍රී", "ජෝර්ජ් ක්ලාසන් හා බෙලින්ග්", "ඩේවිඩ් පේන්ටර් හා අමරසේකර", "ක්ලෝඩ් මොනේ හා ඩෙගාස්", "ශාන්තිනිකේතන 'වොෂ්' (Wash) ජල සායම් ක්‍රමය ලාංකේය කලාකරුවන්ගේ දේශීය අනන්‍යතාව ගොඩනැගීමට උපකාරී විය."),
        q("ජෝර්ජ් කීට්ගේ සුප්‍රකට 'ශ්‍රී ලාංකික මව හා දරුවා' සහ 'කාංජා' වැනි සිතුවම්වල පෙනෙන ප්‍රබල දෘශ්‍ය ශක්තිය කුමකින් ලැබුණේද?", "ඝන රිද්මයානුකූල බාහිර රේඛා හා උණුසුම් වර්ණ", "කුඩා අළු පැහැති පැන්සල් තිත්", "ලෝහ කම්බි හා වීදුරු කැබලි", "තනි සුදු පැහැ කඩදාසි කැපුම්", "අඛණ්ඩව ගලා යන වක්‍ර රේඛාව හා තද තැඹිලි, කහ, දම් වර්ණ කීට්ගේ කලාවේ අනන්‍ය ලක්ෂණයයි."),
        q("ශ්‍රී ලංකාවේ නූතන චිත්‍ර කලාව තුළ 'දෘෂ්ටි කාව්‍ය' හා සංකේතාත්මක අද්භූත සිතුවම් නිර්මාණය කළ රනිල් දෙණිපිටිය වැනි සමකාලීනයන් භාවිත කළේ කුමක්ද?", "දේශීය අත්දැකීම් හා නූතන සංකල්පීය ශිල්ප ක්‍රම", "මිසර හයිරෝග්ලිෆික් ගල් කැටයම්", "පුරාණ ග්‍රීක මැටි බඳුන් ක්‍රම", "මධ්‍යකාලීන යුරෝපීය යුද සන්නාහ", "සමකාලීන ලාංකේය ශිල්පීන් අන්තර්ජාතික නව මාධ්‍ය හා ස්වදේශීය ගැටලු සාර්ථකව සම්බන්ධ කරති."),
        q("පසුකාලීනව ශ්‍රී ලංකාවේ පාසල් චිත්‍ර කලා අධ්‍යාපනය තුළ 'නිර්මාණාත්මක චිත්‍ර කලාව' (Creative Art) ප්‍රචලිත කළ ප්‍රමුඛ කලා ගුරුවරිය හා ශිල්පිනිය කවුද?", "කෝරා අබ්‍රහම් (Cora Abraham)", "මේරි කැසැට් (Mary Cassatt)", "ෆ්‍රීඩා කාලෝ (Frida Kahlo)", "බාබරා හෙප්වර්ත්", "1949 දී මෙල්බර්න් කලා සමාජය හා ළමා චිත්‍ර පාසල ඇරඹූ කෝරා අබ්‍රහම් ළමුන්ගේ නිදහස් ප්‍රකාශනය දිරිමත් කළාය."),
        q("'43 කණ්ඩායමේ චිත්‍ර කලාව යනු බටහිර කලාව අන්ධ ලෙස අනුකරණය කිරීමක් නොවන්නේ ඇයි?", "බටහිර නව ශිල්ප ක්‍රම දේශීය තේමා හා රිද්මයට මුසු කළ නිසා", "ඔවුන් යුරෝපීය තීන්ත කිසිදා භාවිත නොකළ නිසා", "ඔවුන් සියලු දෙනාම පැරීසියේ උපන් අය වූ නිසා", "ඔවුන් මිනිස් රූප ඇඳීම සම්පූර්ණයෙන් තහනම් කළ නිසා", "දේශීය සංස්කෘතිය, ගැමි ජීවිතය හා උපස්ථිතිවාදී-කියුබිසම් ශිල්ප ක්‍රම එක්ව දෙමුහුන් නව්‍ය කලාවක් බිහි විය."),
        q("පැරණි ලාංකේය ජන කතා හා ගැමි චාරිත්‍ර උපහාසාත්මක හා වර්ණවත් රේඛාවලින් සිතුවම් කළ 'දෙවන පරපුරේ' ප්‍රකට ශිල්පියෙකු කවුද?", "ප්‍රසන්න වීරක්කොඩි හෝ ජයසිරි සේමගේ", "පැබ්ලෝ පිකාසෝ", "වින්සන්ට් වෑන් ගෝ", "ක්ලෝඩ් මොනේ", "දේශීය හා ඓතිහාසික සංස්කෘතික තේමා තෙල් සායම් හා ඇක්‍රිලික් මාධ්‍යයෙන් නව පරපුර ඉදිරියට ගෙන ගියහ."),
        q("සමකාලීන ලාංකේය කලාවේ ඩිජිටල් ඡායාරූප, වීඩියෝ හා ස්ථාපන කලාව (New Media Art) පෙන්වන ප්‍රධාන පොදු අවකාශ උළෙල කුමක්ද?", "කොළඹ කලා බියෙනාලේ (Colombo Art Biennale)", "කොළඹ රාජකීය අශ්ව රේස් උළෙල", "මහනුවර පැරණි ශිලා ලේඛන දිනය", "පොළොන්නරුව ගල් කැටයම් ප්‍රදර්ශනය", "ජාත්‍යන්තර හා දේශීය නූතන ශිල්පීන්ගේ නව්‍ය කලා ප්‍රවණතා ප්‍රදර්ශනයට මෙම බියෙනාලේ වේදිකාවක් විය."),
        q("නූතන බටහිර කලාව හා ශ්‍රී ලංකාවේ '43 කණ්ඩායම අධ්‍යයනය කිරීමෙන් අ.පො.ස. (සා.පෙළ) චිත්‍ර කලා සිසුවෙකුට ලැබෙන ප්‍රධානම අවබෝධය කුමක්ද?", "සම්ප්‍රදාය හා නව්‍ය අත්හදා බැලීම් තුළින් අනන්‍යතාවක් ගොඩනැගීම", "සෑම විටම පැරණි ඡායාරූප පමණක් පිටපත් කළ යුතු බව", "තෙල් සායම් හැර අනෙක් සියලු මාධ්‍ය නුසුදුසු බව", "වියුක්ත කලාවට කිසිදු සැලසුමක් හෝ සමතුලිතතාවක් අවශ්‍ය නැති බව", "සම්භාව්‍ය මූලයන් හා නවීන දෘෂ්ටි ක්‍රම සංයෝජනය කර නිර්මාණශීලීව සිතීමට මෙම අධ්‍යයනය මග පාදයි.")
    )
}
